import{_ as n,l as i,o as e,c as s,v as o,p as l,x as t,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"常量传播与折叠","description":"","frontmatter":{"title":"常量传播与折叠","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/constant-propagation.md","filePath":"cs/constant-propagation.md","lastUpdated":1789023840000}'),h={name:"cs/constant-propagation.md"};function m(_,a,f,A,S,u){const r=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=o('<h1 id="常量传播与折叠" tabindex="-1">常量传播与折叠 <a class="header-anchor" href="#常量传播与折叠" aria-label="Permalink to &quot;常量传播与折叠&quot;">​</a></h1><div class="epigraph"><p>若到达此处的定值都是同一常量，则用该常量替换；折叠把纯运算在编译期算完。二者改 IR，不改语言的操作语义约定。</p><footer>—— 据龙书常量传播；Wegman and Zadeck 前的简单迭代；Appel, Modern Compiler Implementation 整理</footer></div><p>上一课<a href="/cs/null-option">空与 Option</a>把类型单元收到显式测试。中端第一课：主干已有<a href="/cs/reaching-def">到达定义</a>、<a href="/cs/ssa-form">SSA</a>。缺口是<strong>用已知常量改写</strong>：传播把名换成数，折叠把 <code>2+3</code> 变成 <code>5</code>。本课钉简单迭代与 SSA 上的替换；条件分支上的「半格」留给下一课 SCCP。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>到达定值给出「哪些写能到这里」。若全部写是 <code>x=3</code>，则读 \\(x\\) 可改成 <code>3</code>。折叠：运算符无副作用则编译期求值。缺口是<strong>替换的合法性</strong>，不是再定义 CFG。</p><p>必须保持<a href="/cs/operational-semantics">操作语义</a>：浮点折叠受 IEEE 与后课 fast-math 约束；除零不能随便折。Option 的 <code>Some 3</code> 可折匹配，<code>None</code> 枝可变成死代码——下一课 ADCE。</p><h3 id="折叠不是预处理器" tabindex="-1">折叠不是预处理器 <a class="header-anchor" href="#折叠不是预处理器" aria-label="Permalink to &quot;折叠不是预处理器&quot;">​</a></h3><p>cpp 的常量是记号层；此处是 IR 层，经过类型与地址计算。不要用 <code>#define N 4</code> 当本课定义。</p><p><span class="marginnote">龙书 9.4。Appel 在 SSA 上把传播写成替换。Kildall 的数据流格是背景。本课简单格：⊤/常量/⊤冲突为全⊤。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>非 SSA：迭代数据流，格元素为「非常量 / 某常量 / 未定义」。SSA：φ 的操作数全同则 φ 成常量；否则该名非常量。折叠在替换后立即做，可能露出新常量。</p>',11)),(e(),l(p,null,{default:t(()=>[c(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20IR%5B%22IR%22%5D%20--%3E%20PROP%5B%22%E4%BC%A0%E6%92%AD%E5%B8%B8%E9%87%8F%22%5D%0A%20%20PROP%20--%3E%20FOLD%5B%22%E6%8A%98%E5%8F%A0%E7%BA%AF%E8%BF%90%E7%AE%97%22%5D%0A%20%20FOLD%20--%3E%20IR%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>与<a href="/cs/abstract-interpretation">抽象解释</a>：平坦常量域是 AI 特例，加宽在此不必，因高度为 2。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>副作用：<code>++</code>、调用、volatile 不折。别名：存内存的「常量」要等别名分析——后课。本课先标量 SSA 名。</p><p>不要折 <code>x/x</code> 为 1 当 \\(x\\) 可能为 0，除非语言 UB 允许——<a href="/cs/undefined-behavior-opt">UB 与优化</a> 再收。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写稀疏条件传播。后课默认：标量常量可在 SSA 上替换。下一课 SCCP：把分支条件也推进格。</p><p>也不把常量传播当过程间内联的替代。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>传播：到达处唯一常量则替换；折叠：纯运算编译期求值。</li><li>SSA 上是替换；格冲突则放弃。</li><li>副作用与浮点规则限制折叠。</li><li>出处：Aho et al. 龙书；Appel；对照 Cousot 平坦域。</li></ul>',9))])}const x=n(h,[["render",m]]);export{P as __pageData,x as default};
